-- Creation part 
CREATE DATABASE IF NOT EXISTS login;
CREATE TABLE IF NOT EXISTS STUDENT_LOGIN (ROLL VARCHAR(20) NOT NULL PRIMARY KEY, PASSWORD VARCHAR(255) NOT NULL, CREATION_TIME TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE STUDENT (ROLL VARCHAR(20) NOT NULL PRIMARY KEY, NAME VARCHAR(100) NOT NULL, EMAIL VARCHAR(150) NOT NULL UNIQUE, DEPT VARCHAR(100) NOT NULL, SEM TINYINT UNSIGNED NULL, is_active TINYINT(1) NOT NULL DEFAULT 1, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT fk_student_login FOREIGN KEY (ROLL) REFERENCES STUDENT_LOGIN(ROLL) ON DELETE CASCADE, INDEX idx_student_name (NAME));
CREATE TABLE TEACHER_LOGIN (TID VARCHAR(20) NOT NULL PRIMARY KEY, PASSWORD VARCHAR(255) NOT NULL, CREATION_TIME TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE TEACHER (TID VARCHAR(20) NOT NULL PRIMARY KEY, NAME VARCHAR(100) NOT NULL, EMAIL VARCHAR(150) NOT NULL UNIQUE, DEPT VARCHAR(100) NOT NULL, DESIGNATION VARCHAR(80) NULL, is_active TINYINT(1) NOT NULL DEFAULT 1, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT fk_teacher_login FOREIGN KEY (TID) REFERENCES TEACHER_LOGIN(TID) ON DELETE CASCADE, INDEX idx_teacher_name (NAME));
CREATE TABLE SESSIONS (SESSION_ID CHAR(64) NOT NULL PRIMARY KEY, ACCOUNT_TYPE ENUM('student','teacher') NOT NULL, ROLL VARCHAR(20) NULL, TID VARCHAR(20) NULL, EXPIRES_AT DATETIME NOT NULL, CREATED_AT TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_session_student FOREIGN KEY (ROLL) REFERENCES STUDENT_LOGIN(ROLL) ON DELETE CASCADE, CONSTRAINT fk_session_teacher FOREIGN KEY (TID) REFERENCES TEACHER_LOGIN(TID) ON DELETE CASCADE, INDEX idx_sessions_roll (ROLL), INDEX idx_sessions_tid (TID), INDEX idx_sessions_exp (EXPIRES_AT), CONSTRAINT chk_session_owner CHECK ((ACCOUNT_TYPE = 'student' AND ROLL IS NOT NULL AND TID IS NULL) OR (ACCOUNT_TYPE = 'teacher' AND TID IS NOT NULL AND ROLL IS NULL)));
CREATE TABLE COURSES (COURSE_ID VARCHAR(20) NOT NULL PRIMARY KEY, COURSE_NAME VARCHAR(150) NOT NULL, CREDITS DECIMAL(3,1) DEFAULT 0.0, TID VARCHAR(20) NULL, is_active TINYINT(1) NOT NULL DEFAULT 1, CONSTRAINT fk_course_teacher FOREIGN KEY (TID) REFERENCES TEACHER(TID) ON DELETE SET NULL);
CREATE TABLE STU_COURSES (`S.ROLL` VARCHAR(20) NOT NULL, C_ID VARCHAR(20) NOT NULL, enrolled_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, status ENUM('enrolled','dropped','completed') NOT NULL DEFAULT 'enrolled', PRIMARY KEY (`S.ROLL`, C_ID), CONSTRAINT fk_stucourses_student FOREIGN KEY (`S.ROLL`) REFERENCES STUDENT(ROLL) ON DELETE CASCADE, CONSTRAINT fk_stucourses_course FOREIGN KEY (C_ID) REFERENCES COURSES(COURSE_ID) ON DELETE CASCADE, INDEX idx_stucourses_course (C_ID));
CREATE TABLE ASSESSMENTS (ASSESSMENT_ID INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, COURSE_ID VARCHAR(20) NOT NULL, TITLE VARCHAR(150) NOT NULL, MAX_MARKS DECIMAL(6,2) NOT NULL, WEIGHT DECIMAL(5,2) NOT NULL DEFAULT 100.00, ASSESSMENT_DATE DATE NOT NULL, CONSTRAINT fk_assessments_course FOREIGN KEY (COURSE_ID) REFERENCES COURSES(COURSE_ID) ON DELETE CASCADE, INDEX idx_assessments_course (COURSE_ID));
CREATE TABLE ACADEMICS (ASSESSMENT_ID INT UNSIGNED NOT NULL, `S.ROLL` VARCHAR(20) NOT NULL, SEM_MARKS DECIMAL(6,2) NOT NULL, REMARKS VARCHAR(255) NULL, entered_by VARCHAR(20) NULL, entered_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (ASSESSMENT_ID, `S.ROLL`), CONSTRAINT fk_academics_assessment FOREIGN KEY (ASSESSMENT_ID) REFERENCES ASSESSMENTS(ASSESSMENT_ID) ON DELETE CASCADE, CONSTRAINT fk_academics_teacher FOREIGN KEY (entered_by) REFERENCES TEACHER(TID) ON DELETE SET NULL, CONSTRAINT chk_marks CHECK (SEM_MARKS >= 0));
CREATE TABLE ATTENDENCE (ATTENDENCE_ID INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, COURSE_ID VARCHAR(20) NOT NULL, `S.ROLL` VARCHAR(20) NOT NULL, CLASS_DATE DATE NOT NULL, ATTENDENCE_STATUS ENUM('present','absent','late','excused') NOT NULL, marked_by VARCHAR(20) NULL, marked_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_attendence_course FOREIGN KEY (COURSE_ID) REFERENCES COURSES(COURSE_ID) ON DELETE CASCADE, CONSTRAINT fk_attendence_teacher FOREIGN KEY (marked_by) REFERENCES TEACHER(TID) ON DELETE SET NULL, UNIQUE KEY uq_attendence (COURSE_ID, `S.ROLL`, CLASS_DATE), INDEX idx_att_roll_date (`S.ROLL`, CLASS_DATE), INDEX idx_att_course_date (COURSE_ID, CLASS_DATE));
CREATE TABLE STUDY_MATERIALS (MATERIAL_ID INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, COURSE_ID VARCHAR(20) NULL, TITLE VARCHAR(200) NOT NULL, DESCRIPTION TEXT NULL, FILE_PATH VARCHAR(500) NOT NULL, FILE_TYPE VARCHAR(50) NOT NULL, FILE_SIZE BIGINT UNSIGNED DEFAULT 0, uploaded_by VARCHAR(20) NULL, UPLOAD_DATE TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_materials_course FOREIGN KEY (COURSE_ID) REFERENCES COURSES(COURSE_ID) ON DELETE CASCADE, CONSTRAINT fk_materials_teacher FOREIGN KEY (uploaded_by) REFERENCES TEACHER(TID) ON DELETE SET NULL, INDEX idx_materials_course (COURSE_ID));
CREATE TABLE NOTICES (NOTICE_ID INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, TITLE VARCHAR(200) NOT NULL, CONTENT TEXT NOT NULL, PRIORITY ENUM('low','normal','high','urgent') NOT NULL DEFAULT 'normal', AUDIENCE ENUM('all','students','teachers') NOT NULL DEFAULT 'all', posted_by VARCHAR(20) NULL, IS_PINNED TINYINT(1) NOT NULL DEFAULT 0, EXPIRES_AT DATETIME NULL, CREATED_AT TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_notices_teacher FOREIGN KEY (posted_by) REFERENCES TEACHER(TID) ON DELETE SET NULL, INDEX idx_notices_feed (IS_PINNED, CREATED_AT));
